extern "C" int strlen(const char *);

class string_buf
{
  char gap[8];
public:
  int char_length;
};

class stringx
{
  char *chars;
  string_buf *my_buf;
public:
  stringx();
  stringx(const stringx &);
  ~stringx();
  void make_room(int);
  void append(const char *, int = -1);
  void append(const stringx &);

  friend stringx operator+(const stringx &, const stringx &);
  friend stringx operator+(const stringx &, const char *);
};

inline stringx operator+(const stringx &lhs, const stringx &rhs)
{
  stringx foo;
  foo.make_room(lhs.my_buf->char_length + rhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs);
  return foo;
}

inline stringx operator+(const stringx &lhs, const char *rhs)
{
  stringx foo;
  int len = strlen(rhs);
  foo.make_room(len + lhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs, len);
  return foo;
}

class script_instance
{
  stringx name;
public:
  const stringx &get_name() const { return name; }
};

class script_executable
{
  char gap[12];
  stringx fullname;
public:
  const stringx &get_fullname() const { return fullname; }
};

class vm_thread
{
  script_instance *instance;
  script_executable *executable;
public:
  script_instance *get_instance() const { return instance; }
  script_executable *get_executable() const { return executable; }
};

class vm_stack
{
  int salloc;
  char *buffer;
  char *SP;
  vm_thread *my_thread;
public:
  bool push(const char *, int);
  vm_thread *get_thread() const { return my_thread; }
};

void error(const stringx &);
typedef float vm_num_t;

struct sys_time_stuct
{
  short year;
  short month;
  short weekday;
  short day;
  short hour;
  short minute;
  short second;
};

class game
{
  char gap[0x214];
  sys_time_stuct systime;
public:
  const sys_time_stuct &get_systime() const { return systime; }
};

extern game *g_game_ptr;

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
    virtual ~function();
    virtual bool operator()(vm_stack &, entry_t) { return true; }
  };
};

class slf_systime_month_t : public script_library_class::function
{
public:
  virtual bool operator()(vm_stack &stack, entry_t entry)
  {
    vm_num_t result = g_game_ptr->get_systime().month;
    if (!stack.push((char *)&result, sizeof(result)))
      error(stack.get_thread()->get_instance()->get_name() + ": stack overflow in " +
            stack.get_thread()->get_executable()->get_fullname());
    return true;
  }
};
